{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Container has direct access to a host filesystem path",
      "resource": "aws_batch_job_definition.pass3",
      "severity": "HIGH",
      "explanation": "The container mounts the Batch host's /tmp directory with write access, allowing the job to read or modify host files and potentially affect other workloads. Using a container-managed volume avoids direct host-path exposure."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Container root filesystem is writable",
      "resource": "aws_batch_job_definition.pass3",
      "severity": "MEDIUM",
      "explanation": "The job definition does not enable readonlyRootFilesystem, so a compromised process can modify the container filesystem. The dedicated /tmp volume can remain writable for temporary data."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Container runs as the image default root user",
      "resource": "aws_batch_job_definition.pass3",
      "severity": "HIGH",
      "explanation": "No user is configured, so the BusyBox container runs as root by default. This increases the impact of container compromise and is especially risky for jobs executing on shared Batch hosts."
    }
  ],
  "patched_code": "resource "aws_batch_job_definition" "pass3" {
  name = "tf_test_batch_job_definition"
  type = "container"

  container_properties = jsonencode({
    "command" : ["ls", "-la"],
    "image" : "busybox",
    "memory" : 1024,
    "vcpus" : 1,
    "readonlyRootFilesystem" : true,
    "user" : "65534",
    "volumes" : [
      {
        "name" : "tmp"
      }
    ],
    "environment" : [
      { "name" : "VARNAME", "value" : "VARVAL" }
    ],
    "mountPoints" : [
      {
        "sourceVolume" : "tmp",
        "containerPath" : "/tmp",
        "readOnly" : false
      }
    ],
    "ulimits" : [
      {
        "hardLimit" : 1024,
        "name" : "nofile",
        "softLimit" : 1024
      }
    ]
  })
}
",
  "fix_summary": "Removed the explicit host /tmp bind mount and retained a container-managed temporary volume. The container now uses a read-only root filesystem and runs as the unprivileged UID 65534."
}
